inline ::flatbuffers::Offset<CLGNode> CreateCLGNode(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Offset<::flatbuffers::String> NODE_ID = 0,
    clgNodeCategory CATEGORY = clgNodeCategory_UNSPECIFIED,
    int32_t BODY_INDEX = -1,
    ::flatbuffers::Offset<CLGRecordRef> IDENTITY = 0,
    int32_t STATE_SOURCE_INDEX = -1,
    int32_t MAX_SIMULTANEOUS_LINKS = -1,
    const CLGVector3 *SITE_POSITION_M = nullptr,
    const CLGVector3 *SITE_UP = nullptr,
    clgElevationGate ELEVATION_GATE = clgElevationGate_UNSPECIFIED,
    double MIN_ELEVATION_RAD = std::numeric_limits<double>::quiet_NaN(),
    clgAttitudeLaw ATTITUDE_LAW = clgAttitudeLaw_UNSPECIFIED,
    const CLGQuaternion *FIXED_ATTITUDE = nullptr,
    ::flatbuffers::Offset<RFMCoordinateSystem> ATTITUDE_FRAME = 0,
    bool HAS_CATEGORY = false,
    bool HAS_BODY_INDEX = false,
    bool HAS_STATE_SOURCE_INDEX = false,
    bool HAS_MAX_SIMULTANEOUS_LINKS = false,
    bool HAS_ELEVATION_GATE = false,
    bool HAS_MIN_ELEVATION_RAD = false,
    bool HAS_ATTITUDE_LAW = false) {
  CLGNodeBuilder builder_(_fbb);
  builder_.add_MIN_ELEVATION_RAD(MIN_ELEVATION_RAD);
  builder_.add_ATTITUDE_FRAME(ATTITUDE_FRAME);
  builder_.add_FIXED_ATTITUDE(FIXED_ATTITUDE);
  builder_.add_SITE_UP(SITE_UP);
  builder_.add_SITE_POSITION_M(SITE_POSITION_M);
  builder_.add_MAX_SIMULTANEOUS_LINKS(MAX_SIMULTANEOUS_LINKS);
  builder_.add_STATE_SOURCE_INDEX(STATE_SOURCE_INDEX);
  builder_.add_IDENTITY(IDENTITY);
  builder_.add_BODY_INDEX(BODY_INDEX);
  builder_.add_NODE_ID(NODE_ID);
  builder_.add_HAS_ATTITUDE_LAW(HAS_ATTITUDE_LAW);
  builder_.add_HAS_MIN_ELEVATION_RAD(HAS_MIN_ELEVATION_RAD);
  builder_.add_HAS_ELEVATION_GATE(HAS_ELEVATION_GATE);
  builder_.add_HAS_MAX_SIMULTANEOUS_LINKS(HAS_MAX_SIMULTANEOUS_LINKS);
  builder_.add_HAS_STATE_SOURCE_INDEX(HAS_STATE_SOURCE_INDEX);
  builder_.add_HAS_BODY_INDEX(HAS_BODY_INDEX);
  builder_.add_HAS_CATEGORY(HAS_CATEGORY);
  builder_.add_ATTITUDE_LAW(ATTITUDE_LAW);
  builder_.add_ELEVATION_GATE(ELEVATION_GATE);
  builder_.add_CATEGORY(CATEGORY);
  return builder_.Finish();
}

