  builder_.add_RANGE_ERROR_BOUND_M(RANGE_ERROR_BOUND_M);
  builder_.add_FRAME_TIME_ERROR_BOUND_S(FRAME_TIME_ERROR_BOUND_S);
  builder_.add_SOURCE_ERROR_BOUND_S(SOURCE_ERROR_BOUND_S);
  builder_.add_ROOT_ERROR_BOUND_S(ROOT_ERROR_BOUND_S);
  builder_.add_ALGORITHM_ID(ALGORITHM_ID);
  builder_.add_STATE_BLOCK_SHA256(STATE_BLOCK_SHA256);
  builder_.add_DEFINITION_SHA256(DEFINITION_SHA256);
  builder_.add_HAS_TIMING(HAS_TIMING);
  builder_.add_HAS_ANALYSIS_SCOPE(HAS_ANALYSIS_SCOPE);
  builder_.add_HAS_MODEL_ERROR_BOUND_S(HAS_MODEL_ERROR_BOUND_S);
  builder_.add_HAS_RANGE_ERROR_BOUND_M(HAS_RANGE_ERROR_BOUND_M);
  builder_.add_HAS_FRAME_TIME_ERROR_BOUND_S(HAS_FRAME_TIME_ERROR_BOUND_S);
  builder_.add_HAS_SOURCE_ERROR_BOUND_S(HAS_SOURCE_ERROR_BOUND_S);
  builder_.add_HAS_ROOT_ERROR_BOUND_S(HAS_ROOT_ERROR_BOUND_S);
